7	 * below). Shared by both storage backends (`sessionStorage` for guests, `localStorage` for
8	 * registered shoppers) — safe, since the two are separate namespaces and can never collide.
9	 * Exported as a single named constant so every reader/writer agrees on it, per conventions.md's
10	 * no-magic-strings rule.
11	 *
12	 * Renamed from the pre-revision `RECENTLY_VIEWED_SESSION_KEY` (same literal value): this key now
13	 * holds a JSON-encoded array of product IDs, not a boolean flag string, so the old name no longer
14	 * described its contents.
15	 */
16	export const RECENTLY_VIEWED_HISTORY_STORAGE_KEY = 'zimm-recently-viewed';
17	
18	const EMPTY_IDS: readonly string[] = [];
19	
20	export type RecentlyViewedHistory = {
21	  hasRecentlyViewed: boolean;
22	  recentlyViewedIds: readonly string[];
23	  markProductViewed: (productId: string) => void;
24	};
