26	/**
27	 * Reads and parses the stored ID list off a given `Storage`. Tolerant of every failure mode a
28	 * real browser can produce: the key missing entirely, `JSON.parse` failing on corrupt data, a
29	 * parsed value that isn't an array, or the storage access itself throwing (Safari private-
30	 * browsing mode throws on both `sessionStorage` and `localStorage` access, not just on write).
31	 * Every failure degrades to "no history" rather than propagating.
32	 */
33	const readStoredIds = (storage: Storage): string[] => {
34	  try {
35	    const raw = storage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY);
36	    if (!raw) return [];
37	    const parsed: unknown = JSON.parse(raw);
38	    return Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string') : [];
39	  } catch {
40	    return [];
41	  }
42	};
43	
44	/**
45	 * Writes the given ID list to a `Storage`, JSON-encoded. Wrapped in try/catch: Safari private-
46	 * browsing mode throws on `setItem`, and a real device can also legitimately hit a storage quota.
47	 * Either way this degrades to "no write happens" rather than throwing further and breaking the
48	 * PDP view-tracking effect this is called from.
49	 *
50	 * @returns `true` if the write succeeded, `false` if it was silently swallowed.
51	 */
52	const writeStoredIds = (storage: Storage, ids: readonly string[]): boolean => {
53	  try {
54	    storage.setItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY, JSON.stringify(ids));
55	    return true;
56	  } catch {
57	    return false;
58	  }
59	};
60	
61	/**
62	 * Moves `productId` to the front of `ids`, removing any existing occurrence first (never a
63	 * duplicate — a re-view of an already-seen product correctly becomes "most recent" again), then
64	 * trims to `RECENTLY_VIEWED_HISTORY_MAX_STORED`, oldest-first (i.e. from the tail).
65	 */
66	const dedupeAndPrepend = (ids: readonly string[], productId: string): string[] => {
67	  const withoutExisting = ids.filter((id) => id !== productId);
68	  return [productId, ...withoutExisting].slice(0, RECENTLY_VIEWED_HISTORY_MAX_STORED);
69	};
