117	  const { isRegistered } = useCustomerType();
118	  const [recentlyViewedIds, setRecentlyViewedIds] = useState<readonly string[]>(EMPTY_IDS);
119	
120	  useEffect(() => {
121	    const storage = isRegistered ? localStorage : sessionStorage;
122	    setRecentlyViewedIds(readStoredIds(storage));
123	  }, [isRegistered]);
