125	  const markProductViewed = useCallback(
126	    (productId: string): void => {
127	      const storage = isRegistered ? localStorage : sessionStorage;
128	      const next = dedupeAndPrepend(readStoredIds(storage), productId);
129	      if (writeStoredIds(storage, next)) {
