1	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
2	import * as React from 'react';
3	import { renderToStaticMarkup } from 'react-dom/server';
4	import { act, renderHook, waitFor } from '@testing-library/react';
5	import { useCustomerType } from '@salesforce/commerce-sdk-react';
6	import { RECENTLY_VIEWED_HISTORY_MAX_STORED } from 'app/constants';
7	import { RECENTLY_VIEWED_HISTORY_STORAGE_KEY, useRecentlyViewedHistory } from './useRecentlyViewedHistory';
8	
9	vi.mock('@salesforce/commerce-sdk-react', () => ({
10	  useCustomerType: vi.fn(),
11	}));
12	
13	const mockUseCustomerType = vi.mocked(useCustomerType);
14	
15	function mockCustomerType(isRegistered: boolean): void {
16	  mockUseCustomerType.mockReturnValue({
17	    customerType: isRegistered ? 'registered' : 'guest',
18	    isGuest: !isRegistered,
19	    isRegistered,
20	    isExternal: false,
21	  });
22	}
23	
24	function seedStoredIds(storage: Storage, ids: readonly string[]): void {
25	  storage.setItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY, JSON.stringify(ids));
26	}
27	
28	describe('useRecentlyViewedHistory', () => {
29	  beforeEach(() => {
30	    vi.clearAllMocks();
31	    window.sessionStorage.clear();
32	    window.localStorage.clear();
33	  });
34	
35	  afterEach(() => {
36	    vi.restoreAllMocks();
37	    window.sessionStorage.clear();
38	    window.localStorage.clear();
39	  });
40	
41	  test('empty storage, guest -> hasRecentlyViewed false, recentlyViewedIds []', async () => {
42	    mockCustomerType(false);
43	
44	    const { result } = renderHook(() => useRecentlyViewedHistory());
45	
46	    await waitFor(() => expect(result.current.hasRecentlyViewed).toBe(false));
47	    expect(result.current.recentlyViewedIds).toEqual([]);
48	  });
49	
50	  test('one stored id, guest -> hasRecentlyViewed true, recentlyViewedIds [id]', async () => {
51	    mockCustomerType(false);
52	    seedStoredIds(window.sessionStorage, ['PRODUCT-1']);
53	
54	    const { result } = renderHook(() => useRecentlyViewedHistory());
55	
56	    await waitFor(() => expect(result.current.hasRecentlyViewed).toBe(true));
57	    expect(result.current.recentlyViewedIds).toEqual(['PRODUCT-1']);
58	  });
59	
60	  // The corrected case this whole revision exists for: the pre-revision hook's
61	  // `hasRecentlyViewed = sessionFlagIsSet || isRegistered` short-circuit would have reported
62	  // `true` here unconditionally, regardless of this shopper's real (empty) tracked history. A
63	  // registered shopper with genuinely zero interim-tracked history must read exactly the same as
64	  // an empty guest.
65	  test('empty storage, REGISTERED -> hasRecentlyViewed false, recentlyViewedIds [] (the corrected short-circuit case)', async () => {
66	    mockCustomerType(true);
67	
68	    const { result } = renderHook(() => useRecentlyViewedHistory());
69	
70	    await waitFor(() => expect(result.current.recentlyViewedIds).toEqual([]));
71	    expect(result.current.hasRecentlyViewed).toBe(false);
72	  });
73	
74	  test('one stored id, registered -> hasRecentlyViewed true, recentlyViewedIds [id] (read from localStorage, not sessionStorage)', async () => {
75	    mockCustomerType(true);
76	    seedStoredIds(window.localStorage, ['PRODUCT-1']);
77	
78	    const { result } = renderHook(() => useRecentlyViewedHistory());
79	
80	    await waitFor(() => expect(result.current.hasRecentlyViewed).toBe(true));
81	    expect(result.current.recentlyViewedIds).toEqual(['PRODUCT-1']);
82	  });
83	
84	  test('first render, before the effect has run -> false/[] (SSR-safety)', () => {
85	    // Deliberately the least favourable case: registered AND history already present in
86	    // localStorage, so a hook that (incorrectly) resolved either synchronously during render --
87	    // instead of deferring both to the effect -- would show non-empty history here instead of
88	    // the safe empty default.
89	    mockCustomerType(true);
90	    seedStoredIds(window.localStorage, ['PRODUCT-1']);
91	
92	    function HistoryHarness() {
93	      const { hasRecentlyViewed, recentlyViewedIds } = useRecentlyViewedHistory();
94	      return React.createElement('span', null, `${hasRecentlyViewed}:${recentlyViewedIds.length}`);
95	    }
96	
97	    // react-dom/server's renderToStaticMarkup never runs `useEffect` bodies -- this is the real
98	    // SSR guarantee, not a simulation of it -- so this proves the hook's return value at the
99	    // exact moment SSR reproduces: before any effect has had a chance to run.
100	    const html = renderToStaticMarkup(React.createElement(HistoryHarness));
101	
102	    expect(html).toBe('<span>false:0</span>');
103	  });
104	
105	  describe('markProductViewed', () => {
106	    test('records a view, guest -> sessionStorage, not localStorage', async () => {
107	      mockCustomerType(false);
108	      const { result } = renderHook(() => useRecentlyViewedHistory());
109	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual([]));
110	
111	      act(() => {
112	        result.current.markProductViewed('PRODUCT-1');
113	      });
114	
115	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual(['PRODUCT-1']));
116	      expect(result.current.hasRecentlyViewed).toBe(true);
117	      expect(JSON.parse(window.sessionStorage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY) ?? '[]')).toEqual([
118	        'PRODUCT-1',
119	      ]);
120	      expect(window.localStorage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY)).toBeNull();
121	    });
122	
123	    test('records a view, registered -> localStorage, not sessionStorage', async () => {
124	      mockCustomerType(true);
125	      const { result } = renderHook(() => useRecentlyViewedHistory());
126	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual([]));
127	
128	      act(() => {
129	        result.current.markProductViewed('PRODUCT-1');
130	      });
131	
132	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual(['PRODUCT-1']));
133	      expect(JSON.parse(window.localStorage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY) ?? '[]')).toEqual([
134	        'PRODUCT-1',
135	      ]);
136	      expect(window.sessionStorage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY)).toBeNull();
137	    });
138	
139	    // AC 2's "most-recent-first" ordering, under repeat views: view A, B, A again -> order must
140	    // be [A, B], not [A, B, A] (a duplicate) or [B, A] (mis-ordered -- the re-view didn't move A
141	    // back to the front).
142	    test('re-viewing an existing id moves it to the front with no duplicate entry', async () => {
143	      mockCustomerType(false);
144	      const { result } = renderHook(() => useRecentlyViewedHistory());
145	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual([]));
146	
147	      act(() => result.current.markProductViewed('A'));
148	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual(['A']));
149	
150	      act(() => result.current.markProductViewed('B'));
151	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual(['B', 'A']));
152	
153	      act(() => result.current.markProductViewed('A'));
154	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual(['A', 'B']));
155	    });
156	
157	    test('writing past the cap trims the oldest (tail) entry', async () => {
158	      mockCustomerType(false);
159	      const fullHistory = Array.from({ length: RECENTLY_VIEWED_HISTORY_MAX_STORED }, (_, i) => `PRODUCT-${i}`);
160	      seedStoredIds(window.sessionStorage, fullHistory);
161	
162	      const { result } = renderHook(() => useRecentlyViewedHistory());
163	      await waitFor(() => expect(result.current.recentlyViewedIds).toHaveLength(RECENTLY_VIEWED_HISTORY_MAX_STORED));
164	
165	      act(() => {
166	        result.current.markProductViewed('PRODUCT-NEW');
167	      });
168	
169	      await waitFor(() => expect(result.current.recentlyViewedIds[0]).toBe('PRODUCT-NEW'));
170	      expect(result.current.recentlyViewedIds).toHaveLength(RECENTLY_VIEWED_HISTORY_MAX_STORED);
171	      // The oldest entry (last in the most-recent-first list) must have been trimmed, not the
172	      // newest.
173	      expect(result.current.recentlyViewedIds).not.toContain(`PRODUCT-${RECENTLY_VIEWED_HISTORY_MAX_STORED - 1}`);
174	    });
175	
176	    test('sessionStorage.setItem throwing -> no exception, no state change', async () => {
177	      mockCustomerType(false);
178	      const { result } = renderHook(() => useRecentlyViewedHistory());
179	      await waitFor(() => expect(result.current.recentlyViewedIds).toEqual([]));
180	
181	      vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
182	        throw new Error('SecurityError: sessionStorage is not available (Safari private mode)');
183	      });
184	
185	      expect(() => act(() => result.current.markProductViewed('PRODUCT-1'))).not.toThrow();
186	      expect(result.current.recentlyViewedIds).toEqual([]);
187	      expect(result.current.hasRecentlyViewed).toBe(false);
188	    });
189	  });
190	
191	  test('sessionStorage.getItem throwing on the initial read -> false/[], no uncaught exception', async () => {
192	    mockCustomerType(false);
193	    vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
194	      throw new Error('SecurityError: sessionStorage is not available (Safari private mode)');
195	    });
196	
197	    const { result } = renderHook(() => useRecentlyViewedHistory());
198	
199	    await waitFor(() => expect(result.current.hasRecentlyViewed).toBe(false));
200	    expect(result.current.recentlyViewedIds).toEqual([]);
201	  });
202	});
