/**
 * Ties the plain Commerce API product shape (`recentlyViewedProductFetch.ts`'s own `getProducts`
 * result) to the rendered `plp`-variation `ZimmProductCard` props, the same "G1" doctrine
 * `recentlyViewedCard.test.ts`/`productInfo.test.ts` document: every assertion below uses a value
 * unique to its own field (the 'large' image group's `alt` is deliberately a value that must never
 * be picked) so a mapping that reads the wrong key fails rather than coincidentally matching.
 *
 * **Was/Now made to fail on purpose first, per this codebase's own established discipline** (see
 * `recentlyViewedCard.test.ts`'s own docblock and the build plan's A4 pass criteria for the same
 * rule stated elsewhere): while authoring the tests below, `selectPriceFields`'s `isOnSale` guard
 * in `recentlyViewedFullHistoryCard.ts` was temporarily inverted (`!priceData.isOnSale &&` in
 * place of `priceData.isOnSale &&`) and the suite re-run — the "on-sale" test failed by asserting
 * `originalPrice` was `undefined` when it should have been `'AUD 650.00'`, and the "not-on-sale"
 * test failed by asserting a defined `originalPrice` when it should have been `undefined`. Both
 * failed exactly as expected, confirming the assertions actually exercise the guard rather than
 * passing regardless of it. The inversion was then reverted and the suite re-run to confirm a
 * clean pass — see the implementation report for the real terminal output of both runs.
 */
import { describe, expect, test, vi } from 'vitest';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import {
  selectRecentlyViewedFullHistoryCard,
  selectGalleryImages,
  selectSizeChipValues,
  resolveOrderableVariant,
  type FormatPrice,
  type RecentlyViewedFullHistoryProduct,
} from './recentlyViewedFullHistoryCard';

const formatPrice: FormatPrice = (amount, currency) => `${currency} ${amount.toFixed(2)}`;

// On sale: two tiered prices (500, 650) with no promotions -- getPriceData's own findLowestPrice
// resolves currentPrice to the base 500 (no promotion beats it), and listPrice to the higher
// tiered price, 650, so isOnSale (500 < 650) is true. Verified independently against a real
// getPriceData call below, not just hand-computed here.
const ON_SALE: RecentlyViewedFullHistoryProduct = {
  id: 'FH-PRODUCT-ID-0001',
  name: 'Natura Mini Dress',
  currency: 'AUD',
  price: 500,
  tieredPrices: [
    { price: 500, quantity: 1 },
    { price: 650, quantity: 1 },
  ],
  imageGroups: [
    {
      viewType: 'medium',
      images: [
        {
          link: 'https://example.test/medium/natura-mini-dress-link.jpg',
          disBaseLink: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
          alt: 'Natura Mini Dress, Ivory',
        },
      ],
    },
    {
      // Wrong viewType -- must never be picked for primaryImage. If it is, the alt assertion
      // below fails.
      viewType: 'large',
      images: [
        {
          link: 'https://example.test/large/natura-mini-dress.jpg',
          alt: 'WRONG VIEWTYPE -- MUST NOT BE PICKED FOR PRIMARY',
        },
      ],
    },
  ],
  variationAttributes: [
    {
      id: 'size',
      name: 'Size',
      values: [
        { value: 'xs', name: 'XS', orderable: true },
        { value: 's', name: 'S', orderable: false },
      ],
    },
    { id: 'color', name: 'Colour', values: [{ value: 'black', name: 'Black', orderable: true }] },
  ],
};

describe('selectRecentlyViewedFullHistoryCard — happy path (on sale)', () => {
  test('maps every field to its correct prop, including was/now pricing, badge (absent on this fixture), and size chips', () => {
    expect(selectRecentlyViewedFullHistoryCard(ON_SALE, formatPrice)).toEqual({
      id: 'FH-PRODUCT-ID-0001',
      href: '/product/FH-PRODUCT-ID-0001',
      name: 'Natura Mini Dress',
      headingLevel: 'h3',
      primaryImage: {
        src: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
        alt: 'Natura Mini Dress, Ivory',
      },
      primaryImageFallbacks: [
        { src: 'https://cdn.example.test/medium/natura-mini-dress.jpg', alt: 'Natura Mini Dress, Ivory' },
      ],
      images: undefined,
      currentPrice: 'AUD 500.00',
      originalPrice: 'AUD 650.00',
      isUnavailable: false,
      badge: undefined,
      variation: 'plp',
      sizeChipValues: [
        { value: 'xs', label: 'XS', isDisabled: false },
        { value: 's', label: 'S', isDisabled: true },
      ],
    });
  });

  test('originalPrice matches an independent getPriceData call for the same fixture, not a hand-picked number', () => {
    const independent = getPriceData(ON_SALE);
    expect(independent.isOnSale).toBe(true);

    const card = selectRecentlyViewedFullHistoryCard(ON_SALE, formatPrice);
    expect(card?.currentPrice).toBe(formatPrice(independent.currentPrice, 'AUD'));
    expect(card?.originalPrice).toBe(formatPrice(independent.listPrice, 'AUD'));
  });

  test('href is a bare /product/{id} path, built from the product id', () => {
    const card = selectRecentlyViewedFullHistoryCard(ON_SALE, formatPrice);
    expect(card?.href).toBe('/product/FH-PRODUCT-ID-0001');
    expect(card?.href).not.toMatch(/^https?:\/\//);
  });

  test('maps the single highest-priority badge when c_productBadges is present (real shape confirmed live on 4673TS251, incl. the unconsumed productBadgeUrl field)', () => {
    const withBadge: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      c_productBadges: [
        { productBadge: 'Runway', productBadgeUrl: '/category/runway' },
        { productBadge: 'Exclusive', productBadgeUrl: '/category/exclusive' },
      ],
    };
    expect(selectRecentlyViewedFullHistoryCard(withBadge, formatPrice)?.badge).toBe('Runway');
  });

  test('leaves badge undefined when c_productBadges is absent', () => {
    expect(
      selectRecentlyViewedFullHistoryCard({ ...ON_SALE, c_productBadges: undefined }, formatPrice)?.badge,
    ).toBeUndefined();
  });
});

describe('selectRecentlyViewedFullHistoryCard — not on sale', () => {
  // Identical price/listPrice (both 500) -- getPriceData's isOnSale is `currentPrice < listPrice`,
  // false when they're equal. Per the build plan's own B2 pass criteria: assert originalPrice is
  // undefined, NOT equal-to-current -- a not-on-sale product must never render a crossed-out price
  // identical to its current one.
  const NOT_ON_SALE: RecentlyViewedFullHistoryProduct = {
    ...ON_SALE,
    tieredPrices: [{ price: 500, quantity: 1 }],
  };

  test('originalPrice is undefined, not equal to currentPrice', () => {
    const independent = getPriceData(NOT_ON_SALE);
    expect(independent.isOnSale).toBe(false);

    const card = selectRecentlyViewedFullHistoryCard(NOT_ON_SALE, formatPrice);
    expect(card?.originalPrice).toBeUndefined();
    expect(card?.currentPrice).toBe('AUD 500.00');
  });
});

describe('selectRecentlyViewedFullHistoryCard — no usable name, no card', () => {
  test('returns null when name is missing', () => {
    expect(selectRecentlyViewedFullHistoryCard({ ...ON_SALE, name: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when name is an empty string', () => {
    expect(selectRecentlyViewedFullHistoryCard({ ...ON_SALE, name: '' }, formatPrice)).toBeNull();
  });

  test('returns null for a nullish product (still loading)', () => {
    expect(selectRecentlyViewedFullHistoryCard(undefined, formatPrice)).toBeNull();
    expect(selectRecentlyViewedFullHistoryCard(null, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedFullHistoryCard — no usable image, no card', () => {
  test('returns null when imageGroups is absent entirely', () => {
    expect(selectRecentlyViewedFullHistoryCard({ ...ON_SALE, imageGroups: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups is an empty array', () => {
    expect(selectRecentlyViewedFullHistoryCard({ ...ON_SALE, imageGroups: [] }, formatPrice)).toBeNull();
  });

  test('returns null when imageGroups filtering matches nothing (no medium viewType)', () => {
    const noMediumGroup: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [{ viewType: 'large', images: [{ link: 'https://example.test/large-only.jpg' }] }],
    };
    expect(selectRecentlyViewedFullHistoryCard(noMediumGroup, formatPrice)).toBeNull();
  });

  test('returns null when the medium group has no images at all', () => {
    const emptyMediumGroup: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [{ viewType: 'medium', images: [] }],
    };
    expect(selectRecentlyViewedFullHistoryCard(emptyMediumGroup, formatPrice)).toBeNull();
  });
});

describe('selectRecentlyViewedFullHistoryCard — price without a paired currency (no guessed currency)', () => {
  test('currentPrice and originalPrice are both undefined when currency is missing, and formatPrice is never called', () => {
    const spy = vi.fn(formatPrice);
    const card = selectRecentlyViewedFullHistoryCard({ ...ON_SALE, currency: undefined }, spy);
    expect(card?.currentPrice).toBeUndefined();
    expect(card?.originalPrice).toBeUndefined();
    expect(spy).not.toHaveBeenCalled();
  });
});

describe('selectGalleryImages — single vs multi image, medium-viewtype-scoped (revised 2026-09-09)', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...ON_SALE, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when the only medium group has just 1 image', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [{ viewType: 'medium', images: [{ link: 'a.jpg' }] }],
    };
    expect(selectGalleryImages(product)).toBeUndefined();
  });

  test('ignores a non-medium group even when it has more images (closes the real bug: no longer "most images wins" regardless of viewtype)', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [
        { viewType: 'medium', images: [{ link: 'a.jpg' }] },
        {
          // A larger, non-medium group -- must NOT be picked even though it has more images. The
          // pre-fix version picked "whichever group has the most images" with no viewtype check at
          // all, which this test would have failed against.
          viewType: 'large',
          images: [
            { link: 'WRONG-VIEWTYPE-1.jpg', alt: 'MUST NOT BE PICKED' },
            { link: 'WRONG-VIEWTYPE-2.jpg', alt: 'MUST NOT BE PICKED' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(product)).toBeUndefined();
  });

  test('picks the medium group, returning its images in filename-sequence order', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            { link: 'https://example.test/medium/2.product.jpg', alt: 'On-model shot' },
            { link: 'https://example.test/medium/1.product.jpg', alt: 'Flat-lay shot' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(product)).toEqual([
      { src: 'https://example.test/medium/1.product.jpg', alt: 'Flat-lay shot' },
      { src: 'https://example.test/medium/2.product.jpg', alt: 'On-model shot' },
    ]);
  });

  test('a multi-image medium product renders images in the mapper output too', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            { link: 'front.jpg', alt: 'front' },
            { link: 'back.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectRecentlyViewedFullHistoryCard(product, formatPrice)?.images).toEqual([
      { src: 'front.jpg', alt: 'front' },
      { src: 'back.jpg', alt: 'back' },
    ]);
  });
});

describe('selectRecentlyViewedFullHistoryCard — colour-scoped image resolution (real 4673TS251-shaped defect)', () => {
  test('picks the medium image group matching the first orderable variant colour, not an unrelated colour group', () => {
    const multiColour: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      variants: [
        { productId: 'MULTI-RED', orderable: true, variationValues: { color: 'RED' } },
        { productId: 'MULTI-BLUE', orderable: true, variationValues: { color: 'BLUE' } },
      ],
      imageGroups: [
        {
          viewType: 'medium',
          variationAttributes: [{ id: 'color', values: [{ value: 'BLUE' }] }],
          images: [{ link: 'https://example.test/medium/blue.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' }],
        },
        {
          viewType: 'medium',
          variationAttributes: [{ id: 'color', values: [{ value: 'RED' }] }],
          images: [{ link: 'https://example.test/medium/red.jpg', alt: 'Natura Mini Dress, Red' }],
        },
      ],
    };
    const card = selectRecentlyViewedFullHistoryCard(multiColour, formatPrice);
    expect(card?.primaryImage.src).toBe('https://example.test/medium/red.jpg');
  });

  test('falls back to a viewtype-only match when a single-colour product has no tagged medium group (real 4673TS251 shape)', () => {
    const singleColourUntagged: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      variants: [{ productId: 'SINGLE-GVSCP', orderable: true, variationValues: { color: 'GVSCP' } }],
      imageGroups: [
        {
          viewType: 'medium',
          // No variationAttributes at all -- nothing to disambiguate for a single-colour product.
          images: [{ link: 'https://example.test/medium/untagged.jpg', alt: 'Untagged single colour' }],
        },
      ],
    };
    const card = selectRecentlyViewedFullHistoryCard(singleColourUntagged, formatPrice);
    expect(card?.primaryImage.src).toBe('https://example.test/medium/untagged.jpg');
  });

  test('never falls back to viewtype-only once the colour-scoped pass already found a real match (does not re-mix colours)', () => {
    const multiColourWithUntaggedDecoy: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      variants: [{ productId: 'MULTI-RED', orderable: true, variationValues: { color: 'RED' } }],
      imageGroups: [
        {
          viewType: 'medium',
          images: [{ link: 'https://example.test/medium/decoy.jpg', alt: 'DECOY -- MUST NOT BE PICKED' }],
        },
        {
          viewType: 'medium',
          variationAttributes: [{ id: 'color', values: [{ value: 'RED' }] }],
          images: [{ link: 'https://example.test/medium/red.jpg', alt: 'Natura Mini Dress, Red' }],
        },
      ],
    };
    const card = selectRecentlyViewedFullHistoryCard(multiColourWithUntaggedDecoy, formatPrice);
    expect(card?.primaryImage.src).toBe('https://example.test/medium/red.jpg');
  });

  test('sorts by the filename sequence number, not raw API array order (real defect: [2,1,3] must resolve to image "1")', () => {
    const outOfOrder: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      variants: undefined,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            { link: 'https://example.test/medium/2.product.jpg', alt: 'On-model shot' },
            { link: 'https://example.test/medium/1.product.jpg', alt: 'Flat-lay shot' },
            { link: 'https://example.test/medium/3.product.jpg', alt: 'Detail shot' },
          ],
        },
      ],
    };
    const card = selectRecentlyViewedFullHistoryCard(outOfOrder, formatPrice);
    expect(card?.primaryImage.src).toBe('https://example.test/medium/1.product.jpg');
  });
});

describe('selectRecentlyViewedFullHistoryCard — isUnavailable from product.master.orderable', () => {
  test('isUnavailable is true when the master record is not orderable', () => {
    const soldOut: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      master: { masterId: ON_SALE.id, orderable: false },
    };
    expect(selectRecentlyViewedFullHistoryCard(soldOut, formatPrice)?.isUnavailable).toBe(true);
  });

  test('isUnavailable is false when the master record is orderable', () => {
    const available: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      master: { masterId: ON_SALE.id, orderable: true },
    };
    expect(selectRecentlyViewedFullHistoryCard(available, formatPrice)?.isUnavailable).toBe(false);
  });

  test('isUnavailable is false when there is no master record at all (never treats missing data as unavailable)', () => {
    const noMaster: RecentlyViewedFullHistoryProduct = { ...ON_SALE, master: undefined };
    expect(selectRecentlyViewedFullHistoryCard(noMaster, formatPrice)?.isUnavailable).toBe(false);
  });
});

describe('resolveOrderableVariant (ported from productListCardMapper.test.ts)', () => {
  const WITH_VARIANTS: RecentlyViewedFullHistoryProduct = {
    ...ON_SALE,
    variants: [
      { productId: 'FH-PRODUCT-ID-0001-XS', price: 500, orderable: true, variationValues: { size: 'xs' } },
      { productId: 'FH-PRODUCT-ID-0001-S', price: 520, orderable: false, variationValues: { size: 's' } },
    ],
  };

  test('resolves the real orderable variant for a matching size', () => {
    expect(resolveOrderableVariant(WITH_VARIANTS, 'xs')).toEqual({
      productId: 'FH-PRODUCT-ID-0001-XS',
      price: 500,
      orderable: true,
    });
  });

  test('reports orderable: false for a matching but out-of-stock size', () => {
    expect(resolveOrderableVariant(WITH_VARIANTS, 's')).toEqual({
      productId: 'FH-PRODUCT-ID-0001-S',
      price: 520,
      orderable: false,
    });
  });

  test('returns null when no variant matches the given size', () => {
    expect(resolveOrderableVariant(WITH_VARIANTS, 'xl')).toBeNull();
  });

  test('returns null when the product has no variants at all', () => {
    expect(resolveOrderableVariant({ ...ON_SALE, variants: undefined }, 'xs')).toBeNull();
  });
});

describe('selectSizeChipValues (ported from productListCardMapper.test.ts)', () => {
  test('returns an empty array when there is no size variation attribute', () => {
    expect(selectSizeChipValues({ ...ON_SALE, variationAttributes: undefined })).toEqual([]);
  });

  test('maps size attribute values to chip values, disabled from orderable', () => {
    expect(selectSizeChipValues(ON_SALE)).toEqual([
      { value: 'xs', label: 'XS', isDisabled: false },
      { value: 's', label: 'S', isDisabled: true },
    ]);
  });

  test('falls back to the raw value as label when name is missing', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      variationAttributes: [{ id: 'size', values: [{ value: 'm', orderable: true }] }],
    };
    expect(selectSizeChipValues(product)).toEqual([{ value: 'm', label: 'm', isDisabled: false }]);
  });
});

/**
 * The "given IDs, fetch real product data" half of SFCC-83/84's interim Recently Viewed data
 * source (build plan §2, "Interim data source" — Einstein is "Not Deployed" on every real
 * Zimmermann site, so this build ships against a browser-tracked view-history stand-in instead).
 * The companion piece is `useRecentlyViewedHistory`
 * (`overrides/app/hooks/useRecentlyViewedHistory.ts`), which supplies the `ids` this hook
 * consumes — every product this hook returns is real, live Commerce Cloud data; only the list of
 * *which* IDs to fetch is sourced from this browser's own tracked history rather than Einstein.
 *
 * Wraps `useProducts` (`@salesforce/commerce-sdk-react`, confirmed real export at
 * `node_modules/@salesforce/commerce-sdk-react/hooks/ShopperProducts/query.js`, re-exported from
 * the package root — the same hook already used at
 * `overrides/app/pages/product-detail/index.tsx:334`), which calls the Shopper Products
 * `getProducts` endpoint. Parameters (`allImages: true`, `perPricebook: true`, `expand: [
 * 'prices', 'promotions', 'images', 'variations']`) match the combination already confirmed
 * correct three independent times this build (Einstein's own `fetchRecProductDetails`
 * — `@salesforce/retail-react-app/app/hooks/use-einstein.js:465-505` — the PLP quick-test mapper,
 * and the `zimmproductcard-live-demo` branch's real-product search call).
 *
 * **The 24-ID cap is a real, hard API limit, not a preference.** Confirmed directly in the SDK's
 * own doc comment: `node_modules/@salesforce/commerce-sdk-react/hooks/ShopperProducts/query.js:29`
 * — *"The maximum number of productIDs that can be requested are 24."* — restated independently
 * in `commerce-sdk-isomorphic`'s own type-declaration prose
 * (`node_modules/commerce-sdk-isomorphic/lib/index.esm.d.ts:58802`: *"hydrate a list of products
 * (max 24)"*). Marcel's explicit decision: cap to the first `GET_PRODUCTS_MAX_IDS_PER_REQUEST`
 * ids, don't batch into multiple requests — a shopper with more than 24 tracked IDs simply never
 * gets the tail of their history fetched by this hook.
 *
 * **SDK param widening for `ids`.** `getProductsQueryParameters.ids` types as `Array<string>`
 * throughout `commerce-sdk-isomorphic` (confirmed at `index.esm.d.ts:57797` and `:58753`), but the
 * real, working base SFCC call this build models (`use-einstein.js`'s `fetchRecProductDetails`)
 * passes a comma-joined string (`ids.join(',')`) straight through — the SDK forwards it verbatim
 * into the query string regardless of the declared array type. This file follows the exact same
 * precedent already used elsewhere in this codebase for this exact field:
 * `overrides/app/pages/product-detail/index.tsx:339`
 * (`ids: childVariantIds.join(',') as unknown as string[]`, commented there as "SDK param
 * widening").
 */
import { useProducts } from '@salesforce/commerce-sdk-react';
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';

/**
 * Hard per-request limit on the Shopper Products `getProducts` endpoint — see this file's own
 * docblock above for the two independent SDK citations confirming this number. Not a UX/product
 * choice, and not adjustable client-side.
 */
const GET_PRODUCTS_MAX_IDS_PER_REQUEST = 24;

export type RecentlyViewedProductFetchResult = {
  /**
   * Real Shopper Products data for as many of the requested (capped) `ids` as the API actually
   * returned, **re-ordered to match `ids`'s own order** — the API's own response order is not
   * documented or guaranteed to match request order, so this hook does the re-ordering rather
   * than assume it. An id the API didn't return at all (e.g. offline or deleted since it was
   * viewed) is silently dropped, not left as a hole in the array.
   */
  products: readonly ShopperProductsTypes.Product[];
  /** `true` only while a real fetch is in flight for a non-empty id list — deliberately `false`,
   *  not the underlying query's own (potentially permanently-pending) loading state, when there
   *  are no ids to fetch at all, since no request is ever made in that case. */
  isLoading: boolean;
};

/**
 * Given a list of product IDs (most-recent-first, per `useRecentlyViewedHistory`), fetches real,
 * live Commerce Cloud product data for them.
 *
 * @param ids - Product IDs to fetch, most-recent-first. A list longer than
 *   `GET_PRODUCTS_MAX_IDS_PER_REQUEST` is truncated to the first N (Marcel's cap-don't-batch
 *   decision) — the endpoint itself has no way to serve more in a single call.
 * @returns `products` — real product data for the requested ids, re-ordered to match `ids` and
 *   with any id the API didn't return dropped. `isLoading` — whether a real fetch is in flight.
 */
export const useRecentlyViewedProductFetch = (ids: readonly string[]): RecentlyViewedProductFetchResult => {
  const cappedIds = ids.slice(0, GET_PRODUCTS_MAX_IDS_PER_REQUEST);

  const { data, isLoading: queryIsLoading } = useProducts(
    {
      parameters: {
        // SDK param widening -- see this file's own docblock for why a comma-joined string is
        // correct here despite the declared `Array<string>` type.
        ids: cappedIds.join(',') as unknown as string[],
        allImages: true,
        perPricebook: true,
        expand: ['prices', 'promotions', 'images', 'variations'],
      },
    },
    {
      // Matches the existing precedent at product-detail/index.tsx:347 for this same hook: don't
      // fire a request at all when there's nothing to ask for.
      enabled: cappedIds.length > 0,
    },
  );

  const productsById = new Map((data?.data ?? []).map((product) => [product.id, product] as const));
  const products = cappedIds
    .map((id) => productsById.get(id))
    .filter((product): product is ShopperProductsTypes.Product => product !== undefined);

  return {
    products,
    // A disabled query (no ids) never transitions out of its initial loading state on some
    // TanStack Query versions/configurations -- AND against `cappedIds.length > 0` so "loading"
    // never lies about a fetch that was never actually started.
    isLoading: cappedIds.length > 0 && queryIsLoading,
  };
};

