import { describe, expect, test, vi } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useProducts } from '@salesforce/commerce-sdk-react';
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { useRecentlyViewedProductFetch } from './recentlyViewedProductFetch';

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useProducts: vi.fn(),
}));

const mockUseProducts = vi.mocked(useProducts);

// Minimal but distinct per id, so a mis-mapped/mis-ordered result is loudly wrong rather than
// coincidentally matching (same doctrine as recentlyViewedCard.test.ts's own fixtures).
const product = (id: string): ShopperProductsTypes.Product => ({ id, name: `Product ${id}` });

function mockProducts(data: ShopperProductsTypes.Product[] | undefined, isLoading = false) {
  mockUseProducts.mockReturnValue({
    data: data ? { limit: data.length, total: data.length, data } : undefined,
    isLoading,
  } as unknown as ReturnType<typeof useProducts>);
}

describe('useRecentlyViewedProductFetch', () => {
  test('calls useProducts with the confirmed parameter combination and a comma-joined ids string', () => {
    mockProducts([product('A'), product('B')]);

    renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(mockUseProducts).toHaveBeenCalledWith(
      {
        parameters: {
          ids: 'A,B',
          allImages: true,
          perPricebook: true,
          expand: ['prices', 'promotions', 'images', 'variations'],
        },
      },
      { enabled: true },
    );
  });

  test('re-orders the API response to match the requested id order, regardless of response order', () => {
    // API returns B before A -- the opposite of request order.
    mockProducts([product('B'), product('A')]);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(result.current.products.map((p) => p.id)).toEqual(['A', 'B']);
  });

  test('silently drops an id the API did not return, without leaving a hole', () => {
    // Only B comes back -- A was requested but is offline/deleted.
    mockProducts([product('B')]);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(result.current.products.map((p) => p.id)).toEqual(['B']);
  });

  test('caps the request at the first 24 ids and never asks for more, even when given more', () => {
    const manyIds = Array.from({ length: 30 }, (_, i) => `ID-${i}`);
    mockProducts([]);

    renderHook(() => useRecentlyViewedProductFetch(manyIds));

    const expectedIds = manyIds.slice(0, 24).join(',');
    expect(mockUseProducts).toHaveBeenCalledWith(
      expect.objectContaining({ parameters: expect.objectContaining({ ids: expectedIds }) }),
      expect.anything(),
    );
  });

  test('products fetched beyond the 24-id cap are never returned, even if somehow present in the response', () => {
    const manyIds = Array.from({ length: 30 }, (_, i) => `ID-${i}`);
    // A response that (hypothetically) included data for an uncapped id must still not surface it
    // -- the cap is enforced on the read side too, not just the outgoing request.
    mockProducts(manyIds.map(product));

    const { result } = renderHook(() => useRecentlyViewedProductFetch(manyIds));

    expect(result.current.products).toHaveLength(24);
    expect(result.current.products.map((p) => p.id)).not.toContain('ID-24');
  });

  test('empty ids -> disables the query, returns no products, and reports isLoading false', () => {
    mockProducts(undefined, true);

    const { result } = renderHook(() => useRecentlyViewedProductFetch([]));

    expect(mockUseProducts).toHaveBeenCalledWith(expect.anything(), { enabled: false });
    expect(result.current.products).toEqual([]);
    // The underlying query mock claims isLoading: true even though disabled -- this hook must
    // not surface that, since no request was ever actually made.
    expect(result.current.isLoading).toBe(false);
  });

  test('isLoading reflects the underlying query only when there are ids to fetch', () => {
    mockProducts(undefined, true);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A']));

    expect(result.current.isLoading).toBe(true);
  });

  test('no data yet (still loading) -> products is an empty array, not a throw', () => {
    mockProducts(undefined, true);

    const { result } = renderHook(() => useRecentlyViewedProductFetch(['A', 'B']));

    expect(result.current.products).toEqual([]);
  });
});

import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
import { getPriceData, filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type {
  ZimmProductCardBaseProps,
  ZimmProductCardPlpVariation,
  ZimmProductCardImage,
} from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';

// This mapper is PLP-only by design, so it returns the narrowed shape directly rather than the
// full `ZimmProductCardProps` union — letting a caller pass the result straight to a
// PLP-typed component (like this page's own `ProductListCard`) with no re-narrowing needed.
type ProductListCardResult = ZimmProductCardBaseProps & ZimmProductCardPlpVariation;

/**
 * `c_productBadges` is a custom SFCC attribute (SFCC-225's own already-merged SCAPI hook) with no
 * typed field on the base SDK's `ProductSearchHit` — it only reaches this shape via that type's
 * own `{[key: string]: any}` index signature. Narrowed here to the one shape this mapper reads,
 * rather than trusting `any` at every call site.
 */
export type ProductListSearchHit = ShopperSearchTypes.ProductSearchHit & {
  c_productBadges?: Array<{ productBadge?: string }>;
};

type RawImage = { alt?: string; disBaseLink?: string; link?: string };

const toCardImage = (image: RawImage | undefined): ZimmProductCardImage | undefined => {
  const src = image?.disBaseLink ?? image?.link;
  if (!src) return undefined;
  return { src, alt: image?.alt ?? '' };
};

/** The correctly-sized product image view — never serve an arbitrary-sized image at thumbnail
 *  size (AGENTS.md's image-sizing guidance). Same constant, same reasoning, as
 *  `recentlyViewedFullHistoryCard.ts`'s own `MEDIUM_VIEW_TYPE`. */
const MEDIUM_VIEW_TYPE = 'medium';

/** The variation-attribute id `filterImageGroups` matches an image group's colour against —
 *  named per conventions.md's no-magic-strings rule. */
const COLOUR_VARIATION_ATTRIBUTE_ID = 'color';

/** The one shape this mapper reads off a `filterImageGroups` result — that function ships from
 *  an untyped base-SFCC module (`@salesforce/retail-react-app` has no types for this subpath, see
 *  `RawImage`'s own comment above for the same reasoning), so this documents an assumed shape
 *  rather than letting `any` propagate silently. */
type ImageGroupShape = { images?: RawImage[] };

/**
 * Extracts the merchandiser-assigned sequence number baked into a catalog image's own filename
 * (e.g. `.../images/1.4673ts251.gvscp.guava-seascape.jpg` → `1`) — 2026-09-09, closing a real,
 * live bug: the array order `filterImageGroups` hands back is NOT guaranteed to match this
 * sequence. Confirmed live on two real products (`4673TS251`, `5487S24`): a newly-published,
 * colour-tagged image group can come back as `[2, 1, 3, 4, ...]` rather than ascending order,
 * which silently swapped this variation's primary/hover images — the flat-lay product shot
 * (always image `1`, confirmed by direct visual inspection on two real products,
 * `4673TS251`/`8637DS241`) showed on hover instead of by default, with the on-model shot (image
 * `2`) showing as primary. Sorting by this number restores the intended sequence regardless of
 * whatever order the API happens to return.
 *
 * Returns `undefined` when the filename doesn't start with a number (e.g. a placeholder/seed
 * product using a non-numeric naming convention) — `sortByImageSequence` below leaves those
 * untouched rather than guessing a position for them.
 */
const extractImageSequenceNumber = (src: string): number | undefined => {
  const filename = src.split('/').pop() ?? '';
  const match = /^(\d+)\./.exec(filename);
  return match ? Number(match[1]) : undefined;
};

/**
 * Sorts by `extractImageSequenceNumber` — a stable sort (guaranteed by the spec since ES2019), so
 * images whose filenames don't carry a sequence number (both compare as "equal") keep their
 * original relative order rather than being shuffled arbitrarily.
 */
const sortByImageSequence = (images: ZimmProductCardImage[]): ZimmProductCardImage[] =>
  [...images].sort((a, b) => {
    const numA = extractImageSequenceNumber(a.src);
    const numB = extractImageSequenceNumber(b.src);
    if (numA === undefined || numB === undefined) return 0;
    return numA - numB;
  });

/**
 * Resolves which real colour this hit's card should show images for — 2026-09-08, closing a
 * real bug: `selectGalleryImages` below used to pick "whichever image group has the most
 * images," with no colour or viewtype awareness at all, so a multi-colour product could show a
 * different colour's photos in its gallery than the one the store itself picked as
 * representative. Two tries, in order:
 *
 * 1. The real variant matching `representedProduct.id` — the store's own already-decided pick,
 *    confirmed live against a real 2-colour product (`ZWNEWPRD04`, 2026-09-09):
 *    `representedProduct.id` resolves to a real entry in `variants[]`, whose own
 *    `variationValues.color` is the answer.
 * 2. First orderable variant, else the first variant at all — same heuristic
 *    `feature/zimmproductcard-live-demo`'s own `resolveDemoVariant` already uses, for the case
 *    `representedProduct` doesn't exist or doesn't match anything real. This is also, by
 *    construction, the only strategy available to a `getProducts`-sourced consumer (Recently
 *    Viewed rail, Full History) — neither carries a `representedProduct` field at all (confirmed
 *    directly against `ShopperProductsTypes.Product`'s own SDK type) — so building this fallback
 *    correctly here is the exact thing that de-risks porting the same approach there later.
 *
 * Returns `undefined` when neither resolves (no variants at all) — callers fall back to an
 * unscoped, viewtype-only lookup in that case (see `selectColourScopedImages` below), never a
 * throw.
 */
export const resolveRepresentativeColour = (hit: ProductListSearchHit): string | undefined => {
  const representedId = hit.representedProduct?.id;
  const representedVariant = hit.variants?.find((variant) => variant.productId === representedId);
  const representedColour = representedVariant?.variationValues?.[COLOUR_VARIATION_ATTRIBUTE_ID];
  if (representedColour) return representedColour;

  const fallbackVariant = hit.variants?.find((variant) => variant.orderable) ?? hit.variants?.[0];
  return fallbackVariant?.variationValues?.[COLOUR_VARIATION_ATTRIBUTE_ID];
};

/**
 * The colour + `medium`-viewtype-scoped image list this hit's card uses — one lookup feeding
 * three separate things in `selectProductListCard` below (the gallery, the hover-swap image, and
 * the broken-image fallback candidates), so the three can never disagree with each other or with
 * the resolved colour above.
 *
 * **Two-pass, not one — confirmed live against a real single-colour product (`4673TS251`,
 * 2026-09-09) this bit the first version of this function.** `filterImageGroups`'s own colour
 * match requires the group to explicitly declare a matching `variationAttributes` entry — but a
 * single-colour product's medium group commonly carries no `variationAttributes` at all (there is
 * only one colour, so nothing to disambiguate), which made a strict colour-scoped lookup exclude
 * the group entirely and silently return zero images. Falling back to a viewtype-only match when
 * the colour-scoped pass finds nothing fixes this — confirmed live, the gallery/hover-swap/
 * fallback data all resolve correctly for this product again. Never the reverse (falling back
 * FROM a real multi-group colour match): that would risk re-mixing colours, the exact bug this
 * whole fix exists to close.
 */
const selectColourScopedImages = (hit: ProductListSearchHit, colour: string | undefined): ZimmProductCardImage[] => {
  const colourScopedGroups = colour
    ? (filterImageGroups(hit.imageGroups ?? [], {
        viewType: MEDIUM_VIEW_TYPE,
        variationValues: { [COLOUR_VARIATION_ATTRIBUTE_ID]: colour },
      }) as ImageGroupShape[])
    : [];

  const groups =
    colourScopedGroups.length > 0
      ? colourScopedGroups
      : (filterImageGroups(hit.imageGroups ?? [], { viewType: MEDIUM_VIEW_TYPE }) as ImageGroupShape[]);

  const images = (groups[0]?.images ?? [])
    .map(toCardImage)
    .filter((image): image is ZimmProductCardImage => Boolean(image));

  return sortByImageSequence(images);
};

/**
 * Picks this hit's gallery from the colour-scoped image list above — matches
 * `ZimmProductCardMedia`'s own "no gallery" contract for 0 or 1 images (returns `undefined`,
 * never a 1-length array).
 */
export const selectGalleryImages = (hit: ProductListSearchHit): ZimmProductCardImage[] | undefined => {
  const images = selectColourScopedImages(hit, resolveRepresentativeColour(hit));
  return images.length > 1 ? images : undefined;
};

/**
 * Reads the "size" variation attribute (if this hit has one) into the shape
 * `ZimmSizeChipGroup` expects. `orderable` on each value already reflects real stock per that
 * specific size, so it maps directly to `isDisabled` with no extra lookup needed.
 */
export const selectSizeChipValues = (hit: ProductListSearchHit): ZimmSizeChipValue[] => {
  const sizeAttribute = hit.variationAttributes?.find((attr) => attr.id === 'size');
  return (sizeAttribute?.values ?? []).map((value) => ({
    value: value.value,
    label: value.name ?? value.value,
    isDisabled: value.orderable === false,
  }));
};

/** What `resolveOrderableVariant` resolves a selected size chip value to — the real, orderable
 *  SKU for that specific size, not the master/represented-product id this hit otherwise defaults
 *  to. `price` is the variant's own (`ShopperSearchTypes.Variant`'s own field, confirmed real via
 *  a live product-detail check, 2026-09-08), which can genuinely differ from the hit's own flat
 *  `price` across sizes (e.g. plus sizes priced higher) — callers should prefer this over the
 *  hit's own price once a variant has been resolved. */
export type ResolvedVariant = {
  productId: string;
  price: number | undefined;
  orderable: boolean;
};

/**
 * Resolves a selected size CHIP VALUE to its real orderable variant — added 2026-09-08 (Gap 3:
 * "size-aware Add to Bag" was previously cosmetic; selecting a chip never changed what got added
 * to the bag at all). Confirmed live against product `4673TS251`: `hit.variants` is real and
 * populated (`expand: [...,'variations']`, already requested by this page's own search call),
 * each entry carrying its own real `productId` (e.g. `4673TS251GVSCP0P`) keyed by
 * `variationValues.size` (e.g. `'0P'`) — exactly the lookup this function performs.
 *
 * Returns `null` when there is no matching variant at all (no `variants` array, or no entry
 * whose `variationValues.size` equals `sizeValue`) — callers are expected to fall back to this
 * hit's own default `representedProduct`/`productId` resolution in that case, the same default
 * that already existed before size-aware add-to-bag was ever selectable.
 */
export const resolveOrderableVariant = (hit: ProductListSearchHit, sizeValue: string): ResolvedVariant | null => {
  const variant = hit.variants?.find((candidate) => candidate.variationValues?.size === sizeValue);
  if (!variant) return null;

  return {
    productId: variant.productId,
    price: variant.price,
    orderable: variant.orderable !== false,
  };
};

/**
 * `getPriceData`'s own return shape (base SFCC, `product-utils.js:123-170`), narrowed to the
 * three fields this mapper reads — ported verbatim from `recentlyViewedFullHistoryCard.ts`'s own
 * identically-named type, same reasoning: `@salesforce/retail-react-app` ships no types for this
 * subpath (falls through `overrides/app/types/vendor.d.ts`'s catch-all ambient `any`), so this
 * documents an assumed shape rather than letting `any` propagate — the real correctness proof is
 * this file's own test comparing against a real `getPriceData` call, not this annotation alone.
 */
type SfccPriceData = {
  /** `findLowestPrice()`'s own `minPrice` — replaces the flat `hit.price` field this mapper used
   *  to read for `currentPrice` (2026-09-08: now sourced from the same call as `originalPrice`,
   *  closing the "two fields could disagree on a multi-variant hit" gap the old code risked). */
  currentPrice: number;
  /** The highest tiered price found — "was" price. `undefined` when the hit has no
   *  `tieredPrices` at all (there is then no maximum to compute). */
  listPrice: number | undefined;
  /** `currentPrice < listPrice` — always `false`, never `true`, when `listPrice` is `undefined`. */
  isOnSale: boolean;
};

/**
 * Derives `currentPrice`/`originalPrice` from a single `getPriceData(hit)` call — ported verbatim
 * from `recentlyViewedFullHistoryCard.ts`'s own `selectPriceFields` (see that file's own docblock
 * for why both fields must come from the one call rather than mixing a flat price field for one
 * and `getPriceData` for the other). No `opts` passed — the default `quantity: 1` is correct for
 * a single-unit card display. No hardcoded fallback currency — if either the price or the
 * currency is absent, formatting is skipped rather than guessed.
 *
 * **Closes 2026-09-08's confirmed gap**: this hit's own `perPricebook: true` + `expand: [...,
 * 'prices']` request (product-list/index.tsx) does carry real tiered pricing — checked directly
 * against a live on-sale product via the Shopper Products detail endpoint (same underlying
 * pricebook data; the search endpoint's own live response couldn't be intercepted directly, since
 * this page's initial data arrives via SSR with no separate client-side request to inspect) —
 * closing the honest "not checked against a live hit" caveat this file's own history carried.
 */
const selectPriceFields = (
  hit: ProductListSearchHit,
  formatPrice: (amount: number, currency: string) => string,
): Pick<ProductListCardResult, 'currentPrice' | 'originalPrice'> => {
  const priceData: SfccPriceData = getPriceData(hit);

  const currentPrice =
    typeof priceData.currentPrice === 'number' && hit.currency
      ? formatPrice(priceData.currentPrice, hit.currency)
      : undefined;

  // Only set when isOnSale is true -- a not-on-sale hit must not render a crossed-out price
  // identical to its current one.
  const originalPrice =
    priceData.isOnSale && typeof priceData.listPrice === 'number' && hit.currency
      ? formatPrice(priceData.listPrice, hit.currency)
      : undefined;

  return { currentPrice, originalPrice };
};

/**
 * Maps one real product-search hit to `ZimmProductCardProps` (`variation: 'plp'`) for this quick
 * test integration. `formatPrice` and `buildUrl` are passed in rather than built here — the page
 * already owns an `intl`-based formatter and `useMultiSite()`'s `buildUrl`, and this stays a pure
 * function with no `react-intl`/hook dependency of its own, the same split the page's existing
 * wishlist-toast handlers already follow. `buildUrl` is what pre-site-prefixes `href` per
 * `ZimmProductCardBaseProps.href`'s own doc comment — `productUrlBuilder` alone has no site/locale
 * awareness (see `overrides/app/components/ui-kits/atoms/zimmNavItem/index.tsx`'s own fix for the
 * same class of bug: an unprefixed href always falls back to the default site on navigation).
 *
 * Returns `null` when there's no usable name or primary image — mirrors `ZimmProductName`'s own
 * "no render without a name" contract, and `ZimmProductCardBaseProps.primaryImage`'s required-ness
 * (a card with neither has nothing to legitimately render).
 */
export const selectProductListCard = (
  hit: ProductListSearchHit,
  formatPrice: (amount: number, currency: string) => string,
  buildUrl: (path: string) => string,
): ProductListCardResult | null => {
  const primaryImage = toCardImage(hit.image);
  if (!hit.productName || !primaryImage) return null;

  const { currentPrice, originalPrice } = selectPriceFields(hit, formatPrice);
  // One resolution feeds the gallery, the hover-swap image, and the fallback candidates below —
  // see `selectColourScopedImages`'s own docblock for why. `primaryImage` above is deliberately
  // NOT re-derived from this list: `hit.image` is the store's own separately-configured "search
  // result" image (confirmed via the SDK's own doc comment: "the first image... for the
  // configured viewtype" — not necessarily `medium`, and not necessarily this colour's `medium`
  // group either), so every entry here is a genuinely distinct, fresh fallback candidate, not a
  // re-listing of an image already tried.
  const scopedImages = selectColourScopedImages(hit, resolveRepresentativeColour(hit));

  return {
    id: hit.productId,
    href: buildUrl(productUrlBuilder({ id: hit.productId })),
    name: hit.productName,
    headingLevel: 'h3',
    primaryImage,
    // Ordered backup candidates if `hit.image` itself fails to load — the real, live defect this
    // closes (confirmed against product `4673TS251`, 2026-09-08): a catalog image group can have
    // a broken image sitting ahead of working ones.
    primaryImageFallbacks: scopedImages,
    // The second image in the same colour-scoped sequence — revealed on hover
    // (`ZimmProductCardMedia`'s own `swapOnHover`/`hoverImage` contract). `undefined` when there
    // is no second image, which that component already treats as "no swap".
    hoverImage: scopedImages[1],
    images: scopedImages.length > 1 ? scopedImages : undefined,
    currentPrice,
    originalPrice,
    isUnavailable: hit.orderable === false,
    // Single highest-priority badge — SFCC-225's own confirmed shape (see the organism's own
    // docblock, "Badge count" note): only one badge is ever shown, never a list.
    badge: hit.c_productBadges?.[0]?.productBadge,
    variation: 'plp',
    sizeChipValues: selectSizeChipValues(hit),
  };
};

