import { describe, test, expect, vi } from 'vitest';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import {
  selectProductListCard,
  selectGalleryImages,
  selectSizeChipValues,
  resolveOrderableVariant,
  resolveRepresentativeColour,
} from './productListCardMapper';

const formatPrice = vi.fn((amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`);
const buildUrl = (path: string) => path;

const baseHit = {
  productId: 'prod-1',
  productName: 'Natura Mini Dress',
  price: 595,
  currency: 'USD',
  image: { link: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
};

describe('selectProductListCard', () => {
  test('returns null when the hit has no product name', () => {
    expect(selectProductListCard({ ...baseHit, productName: undefined }, formatPrice, buildUrl)).toBeNull();
  });

  test('returns null when the hit has no usable image', () => {
    expect(selectProductListCard({ ...baseHit, image: undefined }, formatPrice, buildUrl)).toBeNull();
  });

  test('maps a real hit to plp ZimmProductCardProps', () => {
    const result = selectProductListCard(baseHit, formatPrice, buildUrl);
    expect(result).toEqual({
      id: 'prod-1',
      href: '/product/prod-1',
      name: 'Natura Mini Dress',
      headingLevel: 'h3',
      primaryImage: { src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
      primaryImageFallbacks: [],
      hoverImage: undefined,
      images: undefined,
      currentPrice: 'USD 595.00',
      originalPrice: undefined,
      isUnavailable: false,
      badge: undefined,
      variation: 'plp',
      sizeChipValues: [],
    });
  });

  test('uses disBaseLink over link when both are present', () => {
    const hit = { ...baseHit, image: { link: 'fallback.jpg', disBaseLink: 'preferred.jpg', alt: 'x' } };
    expect(selectProductListCard(hit, formatPrice, buildUrl)?.primaryImage.src).toBe('preferred.jpg');
  });

  // Changed 2026-09-08 (was/now pricing fix): `currentPrice` now comes from `getPriceData`, not
  // a direct read of `hit.price` — and base SFCC's own `findLowestPrice` (product-utils.js:280-
  // 281) deliberately resolves "no price found at all" to `0`, not `undefined` ("we re[s]et the
  // value to 0 as minPrice to be able to use this value on UI" — its own comment). So a hit with
  // no price and no tieredPrices renders "$0.00", not a blank price — confirmed by reading that
  // function directly, not assumed. This replaces the old premise (`hit.price` read directly,
  // `undefined` in → `undefined` out), which no longer describes what the code does.
  test('resolves to a real $0.00 (base SFCC behaviour), not undefined, when there is no price data at all', () => {
    const hit = { ...baseHit, price: undefined };
    expect(selectProductListCard(hit, formatPrice, buildUrl)?.currentPrice).toBe('USD 0.00');
  });

  test('marks isUnavailable true when orderable is false', () => {
    expect(selectProductListCard({ ...baseHit, orderable: false }, formatPrice, buildUrl)?.isUnavailable).toBe(true);
  });

  // Was/now pricing (2026-09-08 fix) — closes the previously-confirmed gap: `originalPrice` used
  // to be hardcoded `undefined` regardless of data. Both fixtures cross-check against a real,
  // independent `getPriceData` call, not a hand-picked expectation — same "G1" doctrine
  // `recentlyViewedFullHistoryCard.test.ts`'s own equivalent tests already document.
  describe('was/now pricing', () => {
    const ON_SALE_HIT = {
      ...baseHit,
      price: 500,
      tieredPrices: [
        { price: 500, quantity: 1 },
        { price: 650, quantity: 1 },
      ],
    };

    test('originalPrice is the real "was" price when the hit is genuinely on sale', () => {
      const independent = getPriceData(ON_SALE_HIT);
      expect(independent.isOnSale).toBe(true);

      const card = selectProductListCard(ON_SALE_HIT, formatPrice, buildUrl);
      expect(card?.currentPrice).toBe('USD 500.00');
      expect(card?.originalPrice).toBe('USD 650.00');
    });

    test('originalPrice stays undefined — never equal to currentPrice — when the hit is not on sale', () => {
      // Identical price/listPrice (both 595) -- getPriceData's isOnSale is `currentPrice < listPrice`,
      // false when they're equal. A not-on-sale hit must never render a crossed-out price
      // identical to its current one.
      const notOnSaleHit = { ...baseHit, tieredPrices: [{ price: 595, quantity: 1 }] };
      const independent = getPriceData(notOnSaleHit);
      expect(independent.isOnSale).toBe(false);

      const card = selectProductListCard(notOnSaleHit, formatPrice, buildUrl);
      expect(card?.originalPrice).toBeUndefined();
      expect(card?.currentPrice).toBe('USD 595.00');
    });
  });

  test('maps the single highest-priority badge when c_productBadges is present', () => {
    const hit = { ...baseHit, c_productBadges: [{ productBadge: 'Runway' }, { productBadge: 'New In' }] };
    expect(selectProductListCard(hit, formatPrice, buildUrl)?.badge).toBe('Runway');
  });

  test('leaves badge undefined when c_productBadges is absent', () => {
    expect(selectProductListCard(baseHit, formatPrice, buildUrl)?.badge).toBeUndefined();
  });

  // Regression coverage for the regional-link bug: the PDP href must be run through the caller's
  // buildUrl() so it carries the current site/locale prefix — see
  // overrides/app/components/ui-kits/atoms/zimmNavItem/index.tsx's own fix for the same class of
  // bug (an unprefixed href always falls back to the default site on navigation).
  test('runs the product href through buildUrl() to carry the current site/locale prefix', () => {
    const regionalBuildUrl = (path: string) => `/uk${path}`;

    expect(selectProductListCard(baseHit, formatPrice, regionalBuildUrl)?.href).toBe('/uk/product/prod-1');
  });
});

describe('resolveOrderableVariant (2026-09-08, Gap 3 fix: size-aware Add to Bag)', () => {
  const hitWithVariants = {
    ...baseHit,
    variants: [
      { productId: 'prod-1-S', price: 595, orderable: true, variationValues: { size: 'S' } },
      { productId: 'prod-1-M', price: 595, orderable: false, variationValues: { size: 'M' } },
      { productId: 'prod-1-L', price: 650, orderable: true, variationValues: { size: 'L' } },
    ],
  };

  test('resolves the real variant productId and price for the selected size', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'L')).toEqual({
      productId: 'prod-1-L',
      price: 650,
      orderable: true,
    });
  });

  test('reports orderable: false for a genuinely unorderable size, rather than dropping it', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'M')).toEqual({
      productId: 'prod-1-M',
      price: 595,
      orderable: false,
    });
  });

  test('returns null when the size value matches no real variant', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'XL')).toBeNull();
  });

  test('returns null when the hit has no variants array at all', () => {
    expect(resolveOrderableVariant(baseHit, 'S')).toBeNull();
  });
});

describe('resolveRepresentativeColour (2026-09-09, real-data-verified colour resolution)', () => {
  // Shape mirrors the real 2-colour product confirmed live (`ZWNEWPRD04`, BLK/TAN, 2026-09-09):
  // `representedProduct.id` resolves to a real entry in `variants[]`, whose own
  // `variationValues.color` is the answer.
  const twoColourHit = {
    ...baseHit,
    representedProduct: { id: 'prod-1-BLK-0' },
    variants: [
      { productId: 'prod-1-BLK-0', orderable: true, variationValues: { color: 'BLK', size: '0' } },
      { productId: 'prod-1-TAN-0', orderable: true, variationValues: { color: 'TAN', size: '0' } },
    ],
  };

  test('resolves via representedProduct when it matches a real variant', () => {
    expect(resolveRepresentativeColour(twoColourHit)).toBe('BLK');
  });

  test('falls back to the first orderable variant when representedProduct matches nothing real', () => {
    const hit = { ...twoColourHit, representedProduct: { id: 'does-not-exist' } };
    expect(resolveRepresentativeColour(hit)).toBe('BLK');
  });

  test('falls back to variants[0] when no variant is orderable at all', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'does-not-exist' },
      variants: [
        { productId: 'prod-1-BLK-0', orderable: false, variationValues: { color: 'BLK', size: '0' } },
        { productId: 'prod-1-TAN-0', orderable: false, variationValues: { color: 'TAN', size: '0' } },
      ],
    };
    expect(resolveRepresentativeColour(hit)).toBe('BLK');
  });

  test('returns undefined when the hit has no variants array at all', () => {
    expect(resolveRepresentativeColour(baseHit)).toBeUndefined();
  });
});

describe('selectGalleryImages (2026-09-09: now colour + viewtype scoped, closing a real bug)', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...baseHit, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when the medium group has only 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [{ viewType: 'medium', images: [{ link: 'a.jpg' }] }],
    };
    expect(selectGalleryImages(hit)).toBeUndefined();
  });

  // Fail-first requirement: a `large` group with MORE images than the correct `medium` one — a
  // viewtype-agnostic "biggest group" pick (the old, buggy behaviour) would choose the wrong one.
  // Confirmed this fails under the old implementation before fixing it.
  test('ignores a differently-viewtype group even when it has more images', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        {
          viewType: 'large',
          images: [{ link: 'l1.jpg' }, { link: 'l2.jpg' }, { link: 'l3.jpg' }],
        },
        {
          viewType: 'medium',
          images: [
            { link: 'm1.jpg', alt: 'front' },
            { link: 'm2.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: 'm1.jpg', alt: 'front' },
      { src: 'm2.jpg', alt: 'back' },
    ]);
  });

  // Real live defect (2026-09-09, confirmed against product `4673TS251`): a single-colour
  // product's medium group commonly carries no `variationAttributes` tag at all (nothing to
  // disambiguate). A strict colour-scoped filter alone excluded this group entirely and silently
  // returned zero images — confirmed this fails without the viewtype-only fallback pass, then
  // fixed. Colour still resolves to a real value here (via representedProduct); the group itself
  // just never declares it.
  test('falls back to a viewtype-only match when the resolved colour matches no group at all', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'prod-1-GVSCP-0' },
      variants: [{ productId: 'prod-1-GVSCP-0', orderable: true, variationValues: { color: 'GVSCP', size: '0' } }],
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            { link: '1.jpg', alt: 'front' },
            { link: '2.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: '1.jpg', alt: 'front' },
      { src: '2.jpg', alt: 'back' },
    ]);
  });

  // Real, live defect (2026-09-09, confirmed against products `4673TS251` and `5487S24`): the
  // API's own array order is NOT guaranteed to match the filename-embedded sequence number. A
  // newly-published, colour-tagged group came back as [image "2", image "1", image "3", ...] —
