  // always image "2") in the primary/default slot and the flat-lay product shot (image "1") in
  // the hover slot — backwards. Fail-first: asserting only "both present" would pass under either
  // order; this asserts the exact resulting sequence.
  test('sorts by the filename-embedded sequence number, not by whatever order the API returns', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'prod-1-GVSCP-0' },
      variants: [{ productId: 'prod-1-GVSCP-0', orderable: true, variationValues: { color: 'GVSCP', size: '0' } }],
      imageGroups: [
        {
          viewType: 'medium',
          variationAttributes: [{ id: 'color', values: [{ value: 'GVSCP' }] }],
          images: [
            { link: '.../2.product.jpg', alt: 'on model' },
            { link: '.../1.product.jpg', alt: 'flat lay' },
            { link: '.../3.product.jpg', alt: 'side' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: '.../1.product.jpg', alt: 'flat lay' },
      { src: '.../2.product.jpg', alt: 'on model' },
      { src: '.../3.product.jpg', alt: 'side' },
    ]);
  });

  // A placeholder/seed product's own non-numeric filename convention (e.g. `PRODUCT.BLK.PZ.jpg`,
  // confirmed live on the `ZWNEWPRD0X` test fixtures) must not be reordered arbitrarily just
  // because it has no sequence number to sort by.
  test('leaves images with no filename sequence number in their original order', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'prod-1-BLK-0' },
      variants: [{ productId: 'prod-1-BLK-0', orderable: true, variationValues: { color: 'BLK', size: '0' } }],
      imageGroups: [
        {
          viewType: 'medium',
          variationAttributes: [{ id: 'color', values: [{ value: 'BLK' }] }],
          images: [
            { link: '.../PRODUCT.BLK.PZ.jpg', alt: 'front' },
            { link: '.../PRODUCT.BLK.BZ.jpg', alt: 'back' },
