        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: '.../PRODUCT.BLK.PZ.jpg', alt: 'front' },
      { src: '.../PRODUCT.BLK.BZ.jpg', alt: 'back' },
