  });

  // Fail-first requirement: BLK's own medium group has fewer images than TAN's — a colour-blind
  // "biggest group" pick would choose the wrong colour's photos here. Mirrors the real,
  // live-verified `ZWNEWPRD04` shape (2026-09-09).
  test('picks the resolved colour-specific medium group, not whichever group has the most images', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'prod-1-BLK-0' },
      variants: [{ productId: 'prod-1-BLK-0', orderable: true, variationValues: { color: 'BLK', size: '0' } }],
