export const RECENTLY_VIEWED_ROUTE = '/recently-viewed';

// SFCC-83/84 — the single source of truth for "how many Recently Viewed cards exist at once,
// per breakpoint." Serves two consumers that both need the same number for different reasons:
// (1) `ZimmRecentlyViewedRail` (index.tsx) — the rail's own actual render cap. **Confirmed with
// Marcel (2026-09-08): a real hard cap, not a "visible before scrolling" soft limit** — the rail
// renders at most this many cards for the current real breakpoint and no more, full stop; a
// shopper cannot scroll a mobile rail to reach a 3rd or later card. This superseded the original
// flat `RECENTLY_VIEWED_RAIL_MAX_ITEMS = 5` (removed) — that constant only ever capped at the
// single Desktop figure regardless of breakpoint, relying on the horizontal-scroll container to
// visually crop the rest at narrower viewports, which is the exact soft-limit behaviour Marcel's
// decision replaced.
// (2) `RecommendedProducts` — the See-Full-History link's own trigger: link
// shows whenever the shopper's tracked history exceeds what the rail will display at the current
// breakpoint. This consumer is unaffected by the cap becoming hard rather than soft — it was
// always asking "does more history exist than the rail shows," which reads identically either
// way.
// Values match zimmRecentlyViewedRail.css.ts's own confirmed per-breakpoint card-width table
// (Mobile 201px cards × 2 = 402px full-bleed, Tablet 256px × 3 = 768px, Desktop 288px × 5 =
// 1440px) — restated here as counts, not re-measured.
//
// **Correction, 2026-09-10 (later same day as the card-width fixes above): the `md`/`xl` key
// names below no longer mean "switches at breakpoints.md/breakpoints.xl."** That claim was true
// when this constant was first written, but went stale the moment
// zimmRecentlyViewedRail.css.ts's own `DESKTOP_UP_QUERY` was corrected (same day, earlier pass)
// to switch card width to Desktop sizing at 1024px — this component's own real Figma Desktop
// threshold — rather than this site's shared `breakpoints.xl` (1280px). Nobody updated this
// comment or this constant's own consumers to match, so between 1024px and 1280px the two
// disagreed: card width already said "Desktop" (5 slots styled), while `useBreakpointValue`
// (which can only switch at this site's own registered breakpoint names) still said "previous
// tier" (3 cards) — confirmed live (Marcel, 2026-09-10: a ~1277px screenshot showing the rail
// styled for 5 cards, only 3 actually rendered, and the See-Full-History link showing as if
// capped at 3). The `md` key is still correct (768px matches both this site's `breakpoints.md`
// AND the rail's own Tablet start — confirmed independently, no drift there). Only `xl`'s
// *meaning* changed: it is now "the rail's own Desktop tier," resolved against
// `RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT` below, not against `breakpoints.xl` — see
// `useRecentlyViewedRailVisibleCount.ts` (`overrides/app/hooks/`) for the real resolution logic
// this now requires, since `useBreakpointValue`'s Chakra-breakpoint-name shorthand cannot express
// a threshold with no registered breakpoint of its own. Both consumers named in this constant's
// own original docblock above (`ZimmRecentlyViewedRail`, `RecommendedProducts`) now go through
// that hook instead of calling `useBreakpointValue` on this object directly.
export const RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS = { base: 2, md: 3, xl: 5 } as const;

// The Recently Viewed Rail's own real Figma "Desktop" breakpoint — 1024px, not this site's shared
// `breakpoints.xl` (1280px). Confirmed directly against the rail's own master component
// (2026-09-10) — see zimmRecentlyViewedRail.css.ts's own "CARD SIZING"/`RAIL_DESKTOP_BREAKPOINT`
// docblock section for the original derivation. Exported here, and imported by both that CSS
// file and `useRecentlyViewedRailVisibleCount.ts`, so the two can never retype this value
// independently and drift apart again the way they just did (see
// RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS's own correction note above) — only one of them is ever
// typed, per .claude/rules/overrideStyling.md's "alias tier is a reference, not a second copy"
// principle.
export const RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT = '64em'; // 1024px

// Fixed 2026-09-10 (first pass), closing a real, live-confirmed bug (Figma-vs-build audit,
// Marcel): the negative-margin trick that lets a `RecommendedProducts` rail bleed edge-to-edge
// inside a `layerStyle="page"` container (PDP's Complete-the-Set/Might-Also-Like/Recently-Viewed,
// PLP's Recently-Viewed) previously used plain Chakra numeric spacing (`{base: -4, md: -8, lg:
// 0}`, i.e. -16px/-32px/0) with no relationship at all to this site's own real page padding. That
// real padding lives in exactly one place, `theme/foundation/gridSystem.ts`'s own
// `grid.containerPadding` (32px through just under 1280px, 40px from 1280px up) — the previous
// value cancelled only half of it on mobile (-16px against a real 32px, leaving the rail visibly
// inset by 16px instead of flush) and dropped to zero 288px too early (Chakra's `lg` step, 992px,
// a full 288px before this site's own real desktop breakpoint at 1280px). Derived directly from
// the same registered `--zimm-grid-margin-*` tokens `gridSystem.ts` itself is built from (see that
// file's own docblock), not re-typed by hand, so the two can never drift apart again.
//
// Corrected again 2026-09-10 (second pass, same day) — the fix above only ever cancelled
// `#app-main`'s own sitewide padding (`zimmAppMain`, globalStyles.ts). Every real call site of
// this constant additionally sits inside a *second*, independent containment layer that applies
// its own horizontal padding on top of that: PDP wraps the whole Product Recommendations block in
// `<PageContainer boxed={true}>` (components/pageContainer/index.tsx — confirmed to have exactly
// one real consumer, this one), and PLP wraps its own rail directly in `<Box layerStyle="page">`
// (base SFCC theme, theme/foundations/layerStyles.js — not overridden here). Two different
// mechanisms, but they resolve to the exact same values: `px: [4, 4, 6, 6, 8]`, Chakra's own stock
// numeric `space` scale (16px/16px/24px/24px/32px), entirely unrelated to this site's own
// `--zimm-grid-margin-*` tokens. Neither value above ever cancelled this second layer, so a real,
// un-bled residual gap remained at every breakpoint even with the fix above in place — 16px below
// 768px, 24px from 768–1279px, 32px from 1280px up — confirmed live (Marcel, DevTools screenshot)
// still visibly inset on PDP mobile, after the rail's own internal card/container fixes were
// already applied and had not closed it.
//
// Now cancels both layers' combined padding at each real step. Needs a third `md` key this time —
// unlike the two `gridSystem.ts`-derived values above (which both change at the same 1280px
// boundary), the second layer here steps at 768px (its own Chakra `md`) *before* `#app-main` steps
// at 1280px, so the two breakpoints don't coincide and a two-key shape can't express the combined
// total correctly across the full range. `1rem`/`1.5rem`/`2rem` are Chakra's own stock
// `space.4`/`.6`/`.8` — the exact values `PageContainer`/`layerStyle="page"` themselves apply —
// written out directly since neither has a `var(--zimm-*)` equivalent to reference.
export const PAGE_CONTENT_BLEED_MX = {
  base: 'calc((var(--zimm-grid-margin-mobile) + 1rem) * -1)', // 32+16=48px
  md: 'calc((var(--zimm-grid-margin-mobile) + 1.5rem) * -1)', // 32+24=56px
  xl: 'calc((var(--zimm-grid-margin-desktop) + 2rem) * -1)', // 40+32=72px
} as const;

// Added 2026-09-10, fixing a real, live-confirmed bug (Figma-vs-build audit, Marcel — three
// DevTools screenshots at iPhone/iPad/Mac widths, each showing the Recently Viewed Full History
// page's own bleed wrapper rendering WIDER than the true viewport). Root cause: `recentlyViewed/
// index.tsx` was wrongly given `mx={PAGE_CONTENT_BLEED_MX}` above — that constant cancels TWO
// stacked layers (`#app-main`'s own padding + PDP/PLP's `PageContainer`/`layerStyle="page"` second
// layer), but the Full History page has no second layer at all (confirmed directly: no
// `PageContainer`, no `layerStyle`, nothing between `#app-main` and this page's own content).
// Cancelling 72px/56px/48px of margin against only 40px/32px/32px of real padding over-cancels by
// exactly the (nonexistent) second layer's own amount at every breakpoint, pushing the page that
// far past the true viewport edge on each side — confirmed against the reported screenshots' own
// numbers (e.g. Desktop: div rendered 1504px wide at a 1440px viewport, margin -72px each side;
// -40px would have landed it at exactly 1440px).
//
// This constant cancels ONLY `#app-main`'s own sitewide padding — the one layer that is genuinely
// universal to every page — so it needs just the two real `gridSystem.ts` breakpoints (`#app-main`
// itself has no intermediate step at 768px, unlike PAGE_CONTENT_BLEED_MX's own second layer, which
// is exactly why that constant needed a third `md` key and this one doesn't).
export const APP_MAIN_BLEED_MX = {
  base: 'calc(var(--zimm-grid-margin-mobile) * -1)', // 32px
  xl: 'calc(var(--zimm-grid-margin-desktop) * -1)', // 40px
} as const;

